-- Content-only, atomic update for cybersecurity; preserves previous assignment criteria.
BEGIN;
CREATE TEMP TABLE legacy_guides(payload jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO legacy_guides(payload) VALUES ($legacy_payload$[{"slug":"cybersecurity","task_number":1,"title":"Security Lab Setup","old_description":"[[AZ]]\nİzolyasiya olunmuş təhlükəsizlik laboratoriyası qur və onun əhatə dairəsi ilə təhlükəsiz istifadə qaydasını yaz.\n\n[[EN]]\nSet up an isolated security lab and document its scope and safe-use rules.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nGələcək kibertəhlükəsizlik tapşırıqları üçün təhlükəsiz laboratoriya planı hazırlayacaqsan. Yalnız öz kompüterində və ya açıq icazə verilmiş test mühitində işləyəcəksən.\n\n## 2. Başlamazdan əvvəl\nFayl/qovluq və lokal kompüter anlayışları, şəbəkə haqqında ilkin bilik. Docker quraşdırmaq alınmırsa, diaqram və sənədlə başla. İcazəsiz real saytları və ictimai IP-ləri skan etmək olmaz.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `safe-security-lab` repo-su yarat. Sıfırdan başla.\n2. `README.md`, `lab-scope.md` və `lab-diagram.md` faylları yarat.\n3. Diaqramda öz kompüterini, test tətbiqini və sintetik test məlumatlarını göstər.\n4. Əhatə dairəsini yaz: yalnız localhost və ya özünün idarə etdiyi test şəbəkəsi.\n5. İcazəli və qadağan olunan əməliyyatları sadala. Real parol, cookie, hesab və şəxsi məlumat istifadə etmə.\n6. Laboratoriyanı başlatma/dayandırma addımlarını sənədləşdir. Docker Compose faylın yoxdursa, onun əmrlərini işlətmə.\n7. Başqa tələbənin təlimatını oxuyub laboratoriyanın sərhədlərini anlaya bildiyini yoxla və repo-nu GitHub-a göndər.\n\n## 4. Konkret nümunə və izah\nSadə lab: kompüterin → yalnız `127.0.0.1`-də açılan öz test səhifən → uydurma məlumat. README-də hansı proqramın lazım olduğunu, onu necə başlatdığını və dayandırdığını yaz. Hələ lab qura bilmirsənsə, yalnız plan hazırladığını qeyd et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, laboratoriya diaqramı, scope və təhlükəsizlik qaydaları, başlatma/dayandırma təlimatı.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nLab ünvanı və sərhədləri aydındır. Diaqram, fayllar və başlatma/dayandırma addımları var; planla işlək lab bir-birindən fərqləndirilib.\n\n[[EN]]\n## 1. Goal\nPlan a safe lab for future cybersecurity exercises. Work only on your own computer or in a test environment you are authorized to use.\n\n## 2. Before you start\nBasic files and folders, local computers, and introductory networking. If Docker is unavailable, start with a diagram and documentation. Never scan real sites or public IPs without permission.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `safe-security-lab`. Start from scratch.\n2. Create `README.md`, `lab-scope.md`, and `lab-diagram.md`.\n3. Draw your computer, a test application, and synthetic test data.\n4. Define the scope as localhost or a test network you control.\n5. List allowed and prohibited actions. Do not use real passwords, cookies, accounts, or personal data.\n6. Document how to start and stop the lab. Do not run Docker Compose commands unless a Compose file exists.\n7. Check whether another student can understand the lab boundaries from your instructions, then push the repository.\n\n## 4. Concrete example and explanation\nA simple lab is your computer → your test page bound to `127.0.0.1` → fictional data. Document required software, start, and stop. If you cannot run it yet, label the deliverable as a plan.\n\n## 5. What to submit\nYour own GitHub repository link, lab diagram, scope and safety rules, and start/stop instructions.\n\n## 6. How to check your work\nState the lab address and boundaries. Include diagram, files, and start/stop steps; distinguish a planned lab from a running one.","new_description":"[[AZ]]\nİzolyasiya olunmuş təhlükəsizlik laboratoriyası qur və onun əhatə dairəsi ilə təhlükəsiz istifadə qaydasını yaz.\n\nPulsuz alətlər: Visual Studio Code, Python (free), Google Docs (personal). Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nSet up an isolated security lab and document its scope and safe-use rules.\n\nFree tools: Visual Studio Code, Python (free), Google Docs (personal). Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** Öz laptopunda localhost lab qovluğu yarat, icazə sərhədini 'yalnız localhost və öz tətbiqim' kimi yaz.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / cybersecurity / task-1` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. Test icazəsi, lokal ünvan və synthetic data qaydalarını yaz. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. Demo tətbiqin sadə təhlükəsiz serverini qur, default olaraq internetə açma. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Lab start/stop, yedəkləmə və heç bir real hesaba toxunmama checklist-i hazırla. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: Öz laptopunda localhost lab qovluğu yarat, icazə sərhədini 'yalnız localhost və öz tətbiqim' kimi yaz. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\nÖz laptopunda localhost lab qovluğu yarat, icazə sərhədini 'yalnız localhost və öz tətbiqim' kimi yaz.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nGələcək kibertəhlükəsizlik tapşırıqları üçün təhlükəsiz laboratoriya planı hazırlayacaqsan. Yalnız öz kompüterində və ya açıq icazə verilmiş test mühitində işləyəcəksən.\n\n## 2. Başlamazdan əvvəl\nFayl/qovluq və lokal kompüter anlayışları, şəbəkə haqqında ilkin bilik. Docker quraşdırmaq alınmırsa, diaqram və sənədlə başla. İcazəsiz real saytları və ictimai IP-ləri skan etmək olmaz.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `safe-security-lab` repo-su yarat. Sıfırdan başla.\n2. `README.md`, `lab-scope.md` və `lab-diagram.md` faylları yarat.\n3. Diaqramda öz kompüterini, test tətbiqini və sintetik test məlumatlarını göstər.\n4. Əhatə dairəsini yaz: yalnız localhost və ya özünün idarə etdiyi test şəbəkəsi.\n5. İcazəli və qadağan olunan əməliyyatları sadala. Real parol, cookie, hesab və şəxsi məlumat istifadə etmə.\n6. Laboratoriyanı başlatma/dayandırma addımlarını sənədləşdir. Docker Compose faylın yoxdursa, onun əmrlərini işlətmə.\n7. Başqa tələbənin təlimatını oxuyub laboratoriyanın sərhədlərini anlaya bildiyini yoxla və repo-nu GitHub-a göndər.\n\n## 4. Konkret nümunə və izah\nSadə lab: kompüterin → yalnız `127.0.0.1`-də açılan öz test səhifən → uydurma məlumat. README-də hansı proqramın lazım olduğunu, onu necə başlatdığını və dayandırdığını yaz. Hələ lab qura bilmirsənsə, yalnız plan hazırladığını qeyd et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, laboratoriya diaqramı, scope və təhlükəsizlik qaydaları, başlatma/dayandırma təlimatı.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nLab ünvanı və sərhədləri aydındır. Diaqram, fayllar və başlatma/dayandırma addımları var; planla işlək lab bir-birindən fərqləndirilib.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Create a localhost-only lab and document its scope and safety rules.\n\n## Free tools and platforms — getting started\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / cybersecurity / task-1` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Document authorized scope, localhost addresses and fictional data. Demonstrate it with source code, a test, file or diagram.\n4. Start a demo server bound locally and never expose it publicly by default. Demonstrate it with source code, a test, file or diagram.\n5. Write a checklist for starting, stopping and cleaning the lab. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Create a localhost-only lab and document its scope and safety rules. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nCreate a localhost-only lab and document its scope and safety rules.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nPlan a safe lab for future cybersecurity exercises. Work only on your own computer or in a test environment you are authorized to use.\n\n## 2. Before you start\nBasic files and folders, local computers, and introductory networking. If Docker is unavailable, start with a diagram and documentation. Never scan real sites or public IPs without permission.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `safe-security-lab`. Start from scratch.\n2. Create `README.md`, `lab-scope.md`, and `lab-diagram.md`.\n3. Draw your computer, a test application, and synthetic test data.\n4. Define the scope as localhost or a test network you control.\n5. List allowed and prohibited actions. Do not use real passwords, cookies, accounts, or personal data.\n6. Document how to start and stop the lab. Do not run Docker Compose commands unless a Compose file exists.\n7. Check whether another student can understand the lab boundaries from your instructions, then push the repository.\n\n## 4. Concrete example and explanation\nA simple lab is your computer → your test page bound to `127.0.0.1` → fictional data. Document required software, start, and stop. If you cannot run it yet, label the deliverable as a plan.\n\n## 5. What to submit\nYour own GitHub repository link, lab diagram, scope and safety rules, and start/stop instructions.\n\n## 6. How to check your work\nState the lab address and boundaries. Include diagram, files, and start/stop steps; distinguish a planned lab from a running one."},{"slug":"cybersecurity","task_number":2,"title":"HTTP and Headers","old_description":"[[AZ]]\nToy web tətbiqində HTTP başlıqlarını yoxla və təhlükəsiz konfiqurasiya təklif et.\n\n[[EN]]\nInspect HTTP headers on a toy web app and propose a safer configuration.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nHTTP sorğusu və cavab başlıqlarını oxuyub təhlükəsizlik və davranış barədə nəticə çıxaracaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz təhlükəsiz lab planın, HTTP request/response, status code və header anlayışları. Yalnız öz lokal test tətbiqindən və ya yazılı nümunələrdən istifadə et.\n\n## 3. Addım-addım icra\n1. Tapşırıq 1-dəki öz lab planını davam etdir.\n2. Lokal test səhifəsi və ya nümunə HTTP response seç.\n3. Status code, Content-Type, Cache-Control, Content-Security-Policy və digər görünən header-ləri qeyd et.\n4. Hər header-in nə iş gördüyünü sadə dillə yaz.\n5. Ən azı 3 risk və düzəliş təklifi göstər; header-in olmamasını avtomatik istismar sübutu kimi təqdim etmə.\n6. Nəticəni README/report-da sənədləşdir.\n\n## 4. Konkret nümunə və izah\nHeader cavabın necə şərh olunacağını bildirən məlumatdır: `Content-Type: text/html` məzmunun HTML olduğunu göstərir. Lokal serverdə brauzerin Network bölməsindən və ya `curl -I http://localhost:PORT` ilə başlıqları oxu; PORT yerinə öz portunu yaz.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin və ya lab hesabatın, redaktə edilmiş request/response nümunələri, header izahları və 3 risk/düzəliş təklifi. Heç bir real hədəfi icazəsiz test etmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nBaşlıq, müşahidə, mümkün risk və təklif ayrı sütunlardadır. Başlığın olmaması təkbaşına təsdiqlənmiş istismar kimi yazılmayıb; 3 təklifin səbəbi izah edilib.\n\n[[EN]]\n## 1. Goal\nRead HTTP request/response headers and explain what they reveal about application behavior and security.\n\n## 2. Before you start\nYour safe lab plan, HTTP requests/responses, status codes, and headers. Use only your own local test app or written examples.\n\n## 3. Step-by-step work\n1. Continue your own lab plan from Task 1.\n2. Choose a local test page or sample HTTP response.\n3. Record status code, Content-Type, Cache-Control, Content-Security-Policy, and other visible headers.\n4. Explain each header in plain language.\n5. Identify at least three risks and fixes; do not treat a missing header alone as proof of exploitability.\n6. Document the findings in a README/report.\n\n## 4. Concrete example and explanation\nHeaders describe how a response is handled: `Content-Type: text/html` identifies HTML. Inspect your local server in the browser Network panel or use `curl -I http://localhost:PORT`, replacing PORT with your port.\n\n## 5. What to submit\nYour own GitHub repository or lab report, redacted request/response examples, header explanations, and three risk/fix suggestions. Never test a real target without authorization.\n\n## 6. How to check your work\nSeparate header, observation, possible risk, and recommendation. Missing headers alone are not confirmed exploits; explain three recommendations.","new_description":"[[AZ]]\nToy web tətbiqində HTTP başlıqlarını yoxla və təhlükəsiz konfiqurasiya təklif et.\n\nPulsuz alətlər: curl, Visual Studio Code, Google Docs (personal). Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nInspect HTTP headers on a toy web app and propose a safer configuration.\n\nFree tools: curl, Visual Studio Code, Google Docs (personal). Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** `curl -I http://localhost:8000` nümunəsində status, Content-Type və təhlükəsizlik başlıqlarını yoxla.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **curl** — https://curl.se. Yalnız öz lokal HTTP servisindən test sorğuları göndər, status və JSON cavablarını yoxla.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / cybersecurity / task-2` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. Öz lokal serverinin response header-lərini browser DevTools və ya curl ilə oxu. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. CSP, X-Content-Type-Options və cookie flag-ları üçün müşahidə cədvəli qur. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Başlıq yoxdursa riskini və təhlükəsiz config nümunəsini izah et. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: `curl -I http://localhost:8000` nümunəsində status, Content-Type və təhlükəsizlik başlıqlarını yoxla. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\n`curl -I http://localhost:8000` nümunəsində status, Content-Type və təhlükəsizlik başlıqlarını yoxla.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nHTTP sorğusu və cavab başlıqlarını oxuyub təhlükəsizlik və davranış barədə nəticə çıxaracaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz təhlükəsiz lab planın, HTTP request/response, status code və header anlayışları. Yalnız öz lokal test tətbiqindən və ya yazılı nümunələrdən istifadə et.\n\n## 3. Addım-addım icra\n1. Tapşırıq 1-dəki öz lab planını davam etdir.\n2. Lokal test səhifəsi və ya nümunə HTTP response seç.\n3. Status code, Content-Type, Cache-Control, Content-Security-Policy və digər görünən header-ləri qeyd et.\n4. Hər header-in nə iş gördüyünü sadə dillə yaz.\n5. Ən azı 3 risk və düzəliş təklifi göstər; header-in olmamasını avtomatik istismar sübutu kimi təqdim etmə.\n6. Nəticəni README/report-da sənədləşdir.\n\n## 4. Konkret nümunə və izah\nHeader cavabın necə şərh olunacağını bildirən məlumatdır: `Content-Type: text/html` məzmunun HTML olduğunu göstərir. Lokal serverdə brauzerin Network bölməsindən və ya `curl -I http://localhost:PORT` ilə başlıqları oxu; PORT yerinə öz portunu yaz.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin və ya lab hesabatın, redaktə edilmiş request/response nümunələri, header izahları və 3 risk/düzəliş təklifi. Heç bir real hədəfi icazəsiz test etmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nBaşlıq, müşahidə, mümkün risk və təklif ayrı sütunlardadır. Başlığın olmaması təkbaşına təsdiqlənmiş istismar kimi yazılmayıb; 3 təklifin səbəbi izah edilib.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Inspect a localhost response status, content type and basic security headers.\n\n## Free tools and platforms — getting started\n- **curl** — https://curl.se. Send test requests only to authorized local endpoints and check status/JSON results.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / cybersecurity / task-2` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Read your own local server's response headers using curl or DevTools. Demonstrate it with source code, a test, file or diagram.\n4. Record CSP, X-Content-Type-Options and cookie flag observations. Demonstrate it with source code, a test, file or diagram.\n5. Explain any missing header and suggest a safe configuration. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Inspect a localhost response status, content type and basic security headers. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nInspect a localhost response status, content type and basic security headers.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nRead HTTP request/response headers and explain what they reveal about application behavior and security.\n\n## 2. Before you start\nYour safe lab plan, HTTP requests/responses, status codes, and headers. Use only your own local test app or written examples.\n\n## 3. Step-by-step work\n1. Continue your own lab plan from Task 1.\n2. Choose a local test page or sample HTTP response.\n3. Record status code, Content-Type, Cache-Control, Content-Security-Policy, and other visible headers.\n4. Explain each header in plain language.\n5. Identify at least three risks and fixes; do not treat a missing header alone as proof of exploitability.\n6. Document the findings in a README/report.\n\n## 4. Concrete example and explanation\nHeaders describe how a response is handled: `Content-Type: text/html` identifies HTML. Inspect your local server in the browser Network panel or use `curl -I http://localhost:PORT`, replacing PORT with your port.\n\n## 5. What to submit\nYour own GitHub repository or lab report, redacted request/response examples, header explanations, and three risk/fix suggestions. Never test a real target without authorization.\n\n## 6. How to check your work\nSeparate header, observation, possible risk, and recommendation. Missing headers alone are not confirmed exploits; explain three recommendations."},{"slug":"cybersecurity","task_number":3,"title":"XSS Awareness","old_description":"[[AZ]]\nLokal nümunədə reflected/stored XSS riskini tanı və təhlükəsiz output encoding tətbiq et.\n\n[[EN]]\nIdentify reflected/stored XSS risk in a local sample and apply safe output encoding.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nCross-site scripting (XSS) riskinin necə yarandığını təhlükəsiz nümunədə öyrənəcək və qorunma yollarını göstərəcəksən.\n\n## 2. Başlamazdan əvvəl\nHTML, JavaScript və brauzerin mətn/HTML göstərməsi barədə ilkin bilik. Yalnız öz lokal nümunən və ya xüsusi təlim labı istifadə et.\n\n## 3. Addım-addım icra\n1. Öz lab repo-nu davam etdir.\n2. İstifadəçi mətnini göstərən sadə lokal səhifə hazırla.\n3. Məlumatın təhlükəsiz mətn kimi göstərilməsi ilə HTML kimi interpretasiya edilməsinin fərqini müqayisə et.\n4. Təhlükəsiz olmayan real payload-ları üçüncü tərəf saytlarda sınama; testləri lokalda zərərsiz nümunələrlə apar.\n5. Output encoding və təhlükəsiz framework API-lərindən istifadəni tətbiq et.\n6. Təhlükəsiz və təhlükəli davranış üçün test və screenshot əlavə et.\n\n## 4. Konkret nümunə və izah\nÖz lokal səhifəndə girişə `<b>Salam</b>` yaz. Mətn kimi göstəriləndə işarələr görünür; HTML kimi göstəriləndə “Salam” qalınlaşır. Bu zərərsiz fərq interpretasiyanı izah edir. Düzəlişdə `textContent` və ya framework-ün təhlükəsiz mətn göstərməsindən istifadə et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, lokal demo, təhlükəsiz/təhlükəli davranış müqayisəsi, düzəliş və testlər. Real saytlara payload göndərmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nEyni giriş üçün əvvəl/sonra screenshot var. Düzəlişdən sonra giriş mətn kimi görünür; sınaq yalnız lokal nümunədə aparılıb.\n\n[[EN]]\n## 1. Goal\nLearn how cross-site scripting (XSS) risks arise and demonstrate defenses in a safe example.\n\n## 2. Before you start\nBasic HTML, JavaScript, and how browsers render text versus HTML. Use only your local example or a dedicated training lab.\n\n## 3. Step-by-step work\n1. Continue your own lab repository.\n2. Build a simple local page that displays user-provided text.\n3. Compare rendering input as safe text with interpreting it as HTML.\n4. Do not test unsafe payloads on third-party sites; use harmless examples locally.\n5. Apply output encoding and safe framework APIs.\n6. Add tests and screenshots for safe and unsafe behavior.\n\n## 4. Concrete example and explanation\nType `<b>Hello</b>` into your own local demo. Text rendering shows the brackets; HTML interpretation makes Hello bold. This harmless comparison illustrates interpretation. Fix with `textContent` or safe framework text rendering.\n\n## 5. What to submit\nYour own GitHub repository, local demo, safe/unsafe behavior comparison, fix, and tests. Do not send payloads to real websites.\n\n## 6. How to check your work\nShow before/after screenshots for the same input. After the fix it renders as text; testing stays within your local demo.","new_description":"[[AZ]]\nLokal nümunədə reflected/stored XSS riskini tanı və təhlükəsiz output encoding tətbiq et.\n\nPulsuz alətlər: Visual Studio Code, Python (free). Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nIdentify reflected/stored XSS risk in a local sample and apply safe output encoding.\n\nFree tools: Visual Studio Code, Python (free). Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** Öz səhifəndə `<b>Salam</b>` mətnini textContent ilə göstər; interpretasiya fərqini ekran görüntüsü ilə izah et.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / cybersecurity / task-3` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. Yalnız lokal HTML/JS demo yarat; üçüncü tərəfə payload göndərmə. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. Eyni mətnin təhlükəsiz mətn və HTML kimi görünüş fərqini screenshot-la qeyd et. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. `textContent` kimi təhlükəsiz output API istifadə edib əvvəl/sonra test yaz. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: Öz səhifəndə `<b>Salam</b>` mətnini textContent ilə göstər; interpretasiya fərqini ekran görüntüsü ilə izah et. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\nÖz səhifəndə `<b>Salam</b>` mətnini textContent ilə göstər; interpretasiya fərqini ekran görüntüsü ilə izah et.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nCross-site scripting (XSS) riskinin necə yarandığını təhlükəsiz nümunədə öyrənəcək və qorunma yollarını göstərəcəksən.\n\n## 2. Başlamazdan əvvəl\nHTML, JavaScript və brauzerin mətn/HTML göstərməsi barədə ilkin bilik. Yalnız öz lokal nümunən və ya xüsusi təlim labı istifadə et.\n\n## 3. Addım-addım icra\n1. Öz lab repo-nu davam etdir.\n2. İstifadəçi mətnini göstərən sadə lokal səhifə hazırla.\n3. Məlumatın təhlükəsiz mətn kimi göstərilməsi ilə HTML kimi interpretasiya edilməsinin fərqini müqayisə et.\n4. Təhlükəsiz olmayan real payload-ları üçüncü tərəf saytlarda sınama; testləri lokalda zərərsiz nümunələrlə apar.\n5. Output encoding və təhlükəsiz framework API-lərindən istifadəni tətbiq et.\n6. Təhlükəsiz və təhlükəli davranış üçün test və screenshot əlavə et.\n\n## 4. Konkret nümunə və izah\nÖz lokal səhifəndə girişə `<b>Salam</b>` yaz. Mətn kimi göstəriləndə işarələr görünür; HTML kimi göstəriləndə “Salam” qalınlaşır. Bu zərərsiz fərq interpretasiyanı izah edir. Düzəlişdə `textContent` və ya framework-ün təhlükəsiz mətn göstərməsindən istifadə et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, lokal demo, təhlükəsiz/təhlükəli davranış müqayisəsi, düzəliş və testlər. Real saytlara payload göndərmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nEyni giriş üçün əvvəl/sonra screenshot var. Düzəlişdən sonra giriş mətn kimi görünür; sınaq yalnız lokal nümunədə aparılıb.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Compare harmless HTML-looking text rendered via textContent versus HTML interpretation locally.\n\n## Free tools and platforms — getting started\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / cybersecurity / task-3` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Build a localhost demo without sending test payloads to third-party sites. Demonstrate it with source code, a test, file or diagram.\n4. Compare text versus HTML rendering of a harmless sample with screenshots. Demonstrate it with source code, a test, file or diagram.\n5. Use safe output APIs such as textContent and verify the fix. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Compare harmless HTML-looking text rendered via textContent versus HTML interpretation locally. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nCompare harmless HTML-looking text rendered via textContent versus HTML interpretation locally.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nLearn how cross-site scripting (XSS) risks arise and demonstrate defenses in a safe example.\n\n## 2. Before you start\nBasic HTML, JavaScript, and how browsers render text versus HTML. Use only your local example or a dedicated training lab.\n\n## 3. Step-by-step work\n1. Continue your own lab repository.\n2. Build a simple local page that displays user-provided text.\n3. Compare rendering input as safe text with interpreting it as HTML.\n4. Do not test unsafe payloads on third-party sites; use harmless examples locally.\n5. Apply output encoding and safe framework APIs.\n6. Add tests and screenshots for safe and unsafe behavior.\n\n## 4. Concrete example and explanation\nType `<b>Hello</b>` into your own local demo. Text rendering shows the brackets; HTML interpretation makes Hello bold. This harmless comparison illustrates interpretation. Fix with `textContent` or safe framework text rendering.\n\n## 5. What to submit\nYour own GitHub repository, local demo, safe/unsafe behavior comparison, fix, and tests. Do not send payloads to real websites.\n\n## 6. How to check your work\nShow before/after screenshots for the same input. After the fix it renders as text; testing stays within your local demo."},{"slug":"cybersecurity","task_number":4,"title":"SQL Injection Awareness","old_description":"[[AZ]]\nTəlim verilənlər bazasında SQL injection səbəbini parameterized query ilə aradan qaldır.\n\n[[EN]]\nFix the cause of SQL injection in a training database using parameterized queries.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nSQL injection riskini izah edəcək və parametrli sorğuların niyə təhlükəsiz olduğunu nümayiş etdirəcəksən.\n\n## 2. Başlamazdan əvvəl\nSQL SELECT, WHERE və parameterized query anlayışları. Lokal test bazası və sintetik data istifadə et; real sistemə sorğu göndərmə.\n\n## 3. Addım-addım icra\n1. Öz lab repo-nu davam etdir.\n2. Sadə lokal axtarış endpoint-i və test bazası qur.\n3. String birləşdirmə ilə qurulan sorğunun riskini kod səviyyəsində izah et; canlı hədəfdə istismar etmə.\n4. Sorğunu parametrli query/prepared statement ilə yenidən yaz.\n5. Normal input, xüsusi simvollar və gözlənilməyən input üçün test yaz.\n6. Kod fərqini və nəticəni hesabatda müqayisə et.\n\n## 4. Konkret nümunə və izah\nLokal kitab axtarışında adı `O'Reilly` olan qeyd işlət. Adı SQL sətrinə birləşdirmək əvəzinə kitabxananın parametrli sorğusuna ver. İstifadə etdiyin dilə uyğun placeholder seç: hər kitabxananın sintaksisi eyni deyil.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, lokal demo, təhlükəli və parametrli sorğu nümunələri, testlər və qısa risk izahı. Testlər yalnız öz labında işləməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nAdi ad, apostroflu ad və boş/yanlış tip üçün gözlənilən nəticə qeyd olunub. İstifadəçi girişi SQL kodundan ayrı ötürülür.\n\n[[EN]]\n## 1. Goal\nExplain SQL injection risk and demonstrate why parameterized queries are safer.\n\n## 2. Before you start\nSQL SELECT/WHERE and parameterized-query basics. Use a local test database and synthetic data; do not query real systems.\n\n## 3. Step-by-step work\n1. Continue your own lab repository.\n2. Create a simple local search endpoint and test database.\n3. Explain the risk of string-built queries at code level; do not exploit a live target.\n4. Rewrite the query using parameters/prepared statements.\n5. Test normal input, special characters, and unexpected input.\n6. Compare the code and results in a report.\n\n## 4. Concrete example and explanation\nUse a fictional local book record named `O'Reilly`. Pass the search term as a query parameter instead of concatenating SQL. Use your library’s placeholder syntax; it varies by driver.\n\n## 5. What to submit\nYour own GitHub repository, local demo, unsafe-versus-parameterized query examples, tests, and a short risk explanation. Tests must run only in your lab.\n\n## 6. How to check your work\nRecord expected results for ordinary text, apostrophes, and empty/wrong-type input. Keep user values separate from SQL code.","new_description":"[[AZ]]\nTəlim verilənlər bazasında SQL injection səbəbini parameterized query ilə aradan qaldır.\n\nPulsuz alətlər: Python (free), Visual Studio Code, Google Docs (personal). Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nFix the cause of SQL injection in a training database using parameterized queries.\n\nFree tools: Python (free), Visual Studio Code, Google Docs (personal). Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** SQLite demo-da `id` dəyərini string birləşdirməsi əvəzinə parametrli sorğu ilə oxu.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / cybersecurity / task-4` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. Kiçik lokal `users` cədvəli və 3 sintetik sətir yarat. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. SQL sorğusunu `?` placeholder və parametr tuple ilə yaz. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Yanlış tip və gözlənilməz mətnlə test et; heç bir real DB və saytı skan etmə. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: SQLite demo-da `id` dəyərini string birləşdirməsi əvəzinə parametrli sorğu ilə oxu. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\nSQLite demo-da `id` dəyərini string birləşdirməsi əvəzinə parametrli sorğu ilə oxu.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nSQL injection riskini izah edəcək və parametrli sorğuların niyə təhlükəsiz olduğunu nümayiş etdirəcəksən.\n\n## 2. Başlamazdan əvvəl\nSQL SELECT, WHERE və parameterized query anlayışları. Lokal test bazası və sintetik data istifadə et; real sistemə sorğu göndərmə.\n\n## 3. Addım-addım icra\n1. Öz lab repo-nu davam etdir.\n2. Sadə lokal axtarış endpoint-i və test bazası qur.\n3. String birləşdirmə ilə qurulan sorğunun riskini kod səviyyəsində izah et; canlı hədəfdə istismar etmə.\n4. Sorğunu parametrli query/prepared statement ilə yenidən yaz.\n5. Normal input, xüsusi simvollar və gözlənilməyən input üçün test yaz.\n6. Kod fərqini və nəticəni hesabatda müqayisə et.\n\n## 4. Konkret nümunə və izah\nLokal kitab axtarışında adı `O'Reilly` olan qeyd işlət. Adı SQL sətrinə birləşdirmək əvəzinə kitabxananın parametrli sorğusuna ver. İstifadə etdiyin dilə uyğun placeholder seç: hər kitabxananın sintaksisi eyni deyil.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, lokal demo, təhlükəli və parametrli sorğu nümunələri, testlər və qısa risk izahı. Testlər yalnız öz labında işləməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nAdi ad, apostroflu ad və boş/yanlış tip üçün gözlənilən nəticə qeyd olunub. İstifadəçi girişi SQL kodundan ayrı ötürülür.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Use parameterized SQLite queries rather than concatenating user-supplied IDs.\n\n## Free tools and platforms — getting started\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / cybersecurity / task-4` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Build a tiny local users table with fictional records. Demonstrate it with source code, a test, file or diagram.\n4. Write queries using parameter placeholders and parameter tuples. Demonstrate it with source code, a test, file or diagram.\n5. Test invalid types and unexpected text against the local sample only. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Use parameterized SQLite queries rather than concatenating user-supplied IDs. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nUse parameterized SQLite queries rather than concatenating user-supplied IDs.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nExplain SQL injection risk and demonstrate why parameterized queries are safer.\n\n## 2. Before you start\nSQL SELECT/WHERE and parameterized-query basics. Use a local test database and synthetic data; do not query real systems.\n\n## 3. Step-by-step work\n1. Continue your own lab repository.\n2. Create a simple local search endpoint and test database.\n3. Explain the risk of string-built queries at code level; do not exploit a live target.\n4. Rewrite the query using parameters/prepared statements.\n5. Test normal input, special characters, and unexpected input.\n6. Compare the code and results in a report.\n\n## 4. Concrete example and explanation\nUse a fictional local book record named `O'Reilly`. Pass the search term as a query parameter instead of concatenating SQL. Use your library’s placeholder syntax; it varies by driver.\n\n## 5. What to submit\nYour own GitHub repository, local demo, unsafe-versus-parameterized query examples, tests, and a short risk explanation. Tests must run only in your lab.\n\n## 6. How to check your work\nRecord expected results for ordinary text, apostrophes, and empty/wrong-type input. Keep user values separate from SQL code."},{"slug":"cybersecurity","task_number":5,"title":"Access Control Review","old_description":"[[AZ]]\nTest tətbiqdə obyekt səviyyəli authorization qaydalarını yoxla və IDOR riskini bağla.\n\n[[EN]]\nReview object-level authorization in a test app and close an IDOR risk.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nAPI və ya lokal tətbiqdə istifadəçinin yalnız icazəsi olan məlumatlara çıxışını yoxlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz test tətbiqin, authentication və authorization fərqi, user ID və resource ownership anlayışları. Yalnız lokal/səlahiyyətli lab-da test et.\n\n## 3. Addım-addım icra\n1. Öz lab layihəni davam etdir.\n2. İki sintetik test istifadəçisi və hərəsinə aid ayrıca resurs yarat.\n3. Login yoxlaması ilə resurs sahiblik yoxlamasının fərqini qeyd et.\n4. Öz test tətbiqində bir istifadəçinin digərinin resurs ID-sinə müraciət etməsini sına.\n5. Server-side ownership check əlavə et və unauthorized/forbidden cavablarını yoxla.\n6. Uğurlu və rədd edilən giriş üçün test yaz; nəticəni şəxsi məlumat olmadan sənədləşdir.\n\n## 4. Konkret nümunə və izah\nAuthentication kimin daxil olduğunu, authorization isə hansı qeydə icazəsi olduğunu müəyyən edir. Lokal testdə A-nın sessiyası ilə B-nin qeydinə sorğu göndər; server məlumatı qaytarmamalı və dəyişikliyə icazə verməməlidir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, access-control test planı, test nəticələri və düzəliş. Təkcə login olmaq başqa istifadəçinin məlumatına giriş icazəsi verməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nA öz qeydini görə bilir, B-nin qeydini görə və dəyişə bilmir. Sessiyasız sorğu da yoxlanılıb; yoxlama yalnız düyməni gizlətməklə məhdudlaşmır.\n\n[[EN]]\n## 1. Goal\nCheck that users can access only resources they are authorized to use.\n\n## 2. Before you start\nYour own test app, authentication versus authorization, user IDs, and resource ownership. Test only in an authorized local lab.\n\n## 3. Step-by-step work\n1. Continue your own lab project.\n2. Create two synthetic test users and separate resources for each.\n3. Explain the difference between checking login and checking resource ownership.\n4. In your own test app, try to access one user's resource using the other test user's ID.\n5. Add a server-side ownership check and verify unauthorized/forbidden responses.\n6. Test allowed and denied access and document results without personal data.\n\n## 4. Concrete example and explanation\nAuthentication identifies a user; authorization decides which resources they may access. In your local lab, request B’s record using A’s session; the server must not disclose or modify it.\n\n## 5. What to submit\nYour own GitHub repository, access-control test plan, test results, and fix. Being logged in must not automatically grant access to another user's data.\n\n## 6. How to check your work\nA can access their own record but cannot read or change B’s. Test unauthenticated requests too; hiding a button is not the server-side check.","new_description":"[[AZ]]\nTest tətbiqdə obyekt səviyyəli authorization qaydalarını yoxla və IDOR riskini bağla.\n\nPulsuz alətlər: Python (free), FastAPI (open source), Google Docs (personal). Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nReview object-level authorization in a test app and close an IDOR risk.\n\nFree tools: Python (free), FastAPI (open source), Google Docs (personal). Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** Uydurma user A öz task-ını görsün, user B-nin task ID-sinə sorğusu isə rədd edilsin.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Python layihəsində lokal HTTP endpoint və Pydantic input modeli yarat; ödənişli server lazım deyil.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / cybersecurity / task-5` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. İki sintetik istifadəçi və hərəsinin bir task-ını yarat. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. Endpoint-də owner yoxlamasının token/rol yoxlamasından sonra işlədiyini göstər. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Başqa istifadəçinin resursunu açma testini 403/404 ilə blokla və ekran sübutu ver. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: Uydurma user A öz task-ını görsün, user B-nin task ID-sinə sorğusu isə rədd edilsin. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\nUydurma user A öz task-ını görsün, user B-nin task ID-sinə sorğusu isə rədd edilsin.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nAPI və ya lokal tətbiqdə istifadəçinin yalnız icazəsi olan məlumatlara çıxışını yoxlayacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz test tətbiqin, authentication və authorization fərqi, user ID və resource ownership anlayışları. Yalnız lokal/səlahiyyətli lab-da test et.\n\n## 3. Addım-addım icra\n1. Öz lab layihəni davam etdir.\n2. İki sintetik test istifadəçisi və hərəsinə aid ayrıca resurs yarat.\n3. Login yoxlaması ilə resurs sahiblik yoxlamasının fərqini qeyd et.\n4. Öz test tətbiqində bir istifadəçinin digərinin resurs ID-sinə müraciət etməsini sına.\n5. Server-side ownership check əlavə et və unauthorized/forbidden cavablarını yoxla.\n6. Uğurlu və rədd edilən giriş üçün test yaz; nəticəni şəxsi məlumat olmadan sənədləşdir.\n\n## 4. Konkret nümunə və izah\nAuthentication kimin daxil olduğunu, authorization isə hansı qeydə icazəsi olduğunu müəyyən edir. Lokal testdə A-nın sessiyası ilə B-nin qeydinə sorğu göndər; server məlumatı qaytarmamalı və dəyişikliyə icazə verməməlidir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, access-control test planı, test nəticələri və düzəliş. Təkcə login olmaq başqa istifadəçinin məlumatına giriş icazəsi verməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nA öz qeydini görə bilir, B-nin qeydini görə və dəyişə bilmir. Sessiyasız sorğu da yoxlanılıb; yoxlama yalnız düyməni gizlətməklə məhdudlaşmır.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Ensure fictional User A cannot read fictional User B's task by guessing an ID.\n\n## Free tools and platforms — getting started\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **FastAPI (open source)** — https://fastapi.tiangolo.com. Create local Python HTTP endpoints with Pydantic validation; paid hosting is unnecessary.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / cybersecurity / task-5` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Create two fictional users with one task each. Demonstrate it with source code, a test, file or diagram.\n4. Validate ownership after authentication rather than trusting user input. Demonstrate it with source code, a test, file or diagram.\n5. Test cross-user resource access and return a safe deny response. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Ensure fictional User A cannot read fictional User B's task by guessing an ID. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nEnsure fictional User A cannot read fictional User B's task by guessing an ID.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nCheck that users can access only resources they are authorized to use.\n\n## 2. Before you start\nYour own test app, authentication versus authorization, user IDs, and resource ownership. Test only in an authorized local lab.\n\n## 3. Step-by-step work\n1. Continue your own lab project.\n2. Create two synthetic test users and separate resources for each.\n3. Explain the difference between checking login and checking resource ownership.\n4. In your own test app, try to access one user's resource using the other test user's ID.\n5. Add a server-side ownership check and verify unauthorized/forbidden responses.\n6. Test allowed and denied access and document results without personal data.\n\n## 4. Concrete example and explanation\nAuthentication identifies a user; authorization decides which resources they may access. In your local lab, request B’s record using A’s session; the server must not disclose or modify it.\n\n## 5. What to submit\nYour own GitHub repository, access-control test plan, test results, and fix. Being logged in must not automatically grant access to another user's data.\n\n## 6. How to check your work\nA can access their own record but cannot read or change B’s. Test unauthenticated requests too; hiding a button is not the server-side check."},{"slug":"cybersecurity","task_number":6,"title":"JWT Review","old_description":"[[AZ]]\nJWT qəbulunu yoxla: imza, issuer, audience, expiry və alg seçimi üzrə testlər əlavə et.\n\n[[EN]]\nValidate JWT handling with tests for signature, issuer, audience, expiry, and algorithm choice.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nJWT token-in strukturunu və yoxlanmalı təhlükəsizlik xüsusiyyətlərini araşdıracaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz test tətbiqin, JSON, token expiration və signature anlayışları. Real token, cookie və hesab məlumatını paylaşma.\n\n## 3. Addım-addım icra\n1. Öz lab repo-nu davam etdir.\n2. Uydurma test token-i və ya redaktə edilmiş nümunə seç.\n3. Header, payload və signature hissələrini izah et; payload-un şifrələnmiş olmadığını qeyd et.\n4. Expiration, issuer, audience və imza yoxlamasının rolunu yaz.\n5. Lokal testdə vaxtı keçmiş və dəyişdirilmiş nümunələrin rədd edilməsini yoxla.\n6. Token-i log-lara yazmamaq və secret-i paylaşmamaq üçün checklist əlavə et.\n\n## 4. Konkret nümunə və izah\nJWT üç hissədən ibarətdir: header, payload və imza. Payload oxuna bilər; həssas məlumat üçün gizli anbar deyil. `exp` bitmə vaxtıdır, `iss` tokeni verən, `aud` nəzərdə tutulan alıcıdır. Etibarlı kitabxana ilə lokal test açarı istifadə et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, redaktə edilmiş token nümunəsi, JWT yoxlama checklist-i və test nəticələri. Real session token və ya secret təqdim etmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nİmza, müddət, issuer və audience yoxlanılır. Dəyişdirilmiş və vaxtı bitmiş tokenlər rədd olunur; paylaşdığın hesabatda real token/açar yoxdur.\n\n[[EN]]\n## 1. Goal\nReview JWT structure and the security checks an application should perform.\n\n## 2. Before you start\nYour own test app, JSON, token expiration, and signature concepts. Never share real tokens, cookies, or account data.\n\n## 3. Step-by-step work\n1. Continue your own lab repository.\n2. Use a fictional test token or a redacted example.\n3. Explain header, payload, and signature, noting that the payload is not encrypted by default.\n4. Describe expiration, issuer, audience, and signature validation.\n5. In a local test, verify that expired and altered examples are rejected.\n6. Add a checklist for keeping tokens out of logs and protecting secrets.\n\n## 4. Concrete example and explanation\nJWT has header, payload, and signature. The payload is readable, not a secret store. `exp` is expiry, `iss` the issuer, and `aud` the intended audience. Use a maintained library and a local test key.\n\n## 5. What to submit\nYour own GitHub repository, a redacted token example, a JWT validation checklist, and test results. Never submit real session tokens or secrets.\n\n## 6. How to check your work\nValidate signature, expiry, issuer, and audience. Reject changed and expired tokens; share no real tokens or keys in the report.","new_description":"[[AZ]]\nJWT qəbulunu yoxla: imza, issuer, audience, expiry və alg seçimi üzrə testlər əlavə et.\n\nPulsuz alətlər: Python (free), Google Docs (personal). Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nValidate JWT handling with tests for signature, issuer, audience, expiry, and algorithm choice.\n\nFree tools: Python (free), Google Docs (personal). Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** Öz yaratdığın sintetik JWT-də `exp`, `iss`, `aud` sahələrinin nə üçün olduğunu təsvir et.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / cybersecurity / task-6` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. JWT strukturu (header.payload.signature) və imza yoxlamasını sənədləşdir. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. Öz test açarınla exp/iss/aud doğrulama funksiyası qur; real token paylaşma. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Vaxtı bitmiş və yanlış imzalı sintetik tokenlərin bloklandığını yoxla. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: Öz yaratdığın sintetik JWT-də `exp`, `iss`, `aud` sahələrinin nə üçün olduğunu təsvir et. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\nÖz yaratdığın sintetik JWT-də `exp`, `iss`, `aud` sahələrinin nə üçün olduğunu təsvir et.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nJWT token-in strukturunu və yoxlanmalı təhlükəsizlik xüsusiyyətlərini araşdıracaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz test tətbiqin, JSON, token expiration və signature anlayışları. Real token, cookie və hesab məlumatını paylaşma.\n\n## 3. Addım-addım icra\n1. Öz lab repo-nu davam etdir.\n2. Uydurma test token-i və ya redaktə edilmiş nümunə seç.\n3. Header, payload və signature hissələrini izah et; payload-un şifrələnmiş olmadığını qeyd et.\n4. Expiration, issuer, audience və imza yoxlamasının rolunu yaz.\n5. Lokal testdə vaxtı keçmiş və dəyişdirilmiş nümunələrin rədd edilməsini yoxla.\n6. Token-i log-lara yazmamaq və secret-i paylaşmamaq üçün checklist əlavə et.\n\n## 4. Konkret nümunə və izah\nJWT üç hissədən ibarətdir: header, payload və imza. Payload oxuna bilər; həssas məlumat üçün gizli anbar deyil. `exp` bitmə vaxtıdır, `iss` tokeni verən, `aud` nəzərdə tutulan alıcıdır. Etibarlı kitabxana ilə lokal test açarı istifadə et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, redaktə edilmiş token nümunəsi, JWT yoxlama checklist-i və test nəticələri. Real session token və ya secret təqdim etmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nİmza, müddət, issuer və audience yoxlanılır. Dəyişdirilmiş və vaxtı bitmiş tokenlər rədd olunur; paylaşdığın hesabatda real token/açar yoxdur.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Explain exp, iss and aud claims on fictional tokens you generate locally.\n\n## Free tools and platforms — getting started\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / cybersecurity / task-6` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Explain header.payload.signature and verified-token requirements. Demonstrate it with source code, a test, file or diagram.\n4. Validate exp/iss/aud on tokens signed with a local test key. Demonstrate it with source code, a test, file or diagram.\n5. Reject expired and invalid-signature fictional tokens, never real credentials. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Explain exp, iss and aud claims on fictional tokens you generate locally. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nExplain exp, iss and aud claims on fictional tokens you generate locally.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nReview JWT structure and the security checks an application should perform.\n\n## 2. Before you start\nYour own test app, JSON, token expiration, and signature concepts. Never share real tokens, cookies, or account data.\n\n## 3. Step-by-step work\n1. Continue your own lab repository.\n2. Use a fictional test token or a redacted example.\n3. Explain header, payload, and signature, noting that the payload is not encrypted by default.\n4. Describe expiration, issuer, audience, and signature validation.\n5. In a local test, verify that expired and altered examples are rejected.\n6. Add a checklist for keeping tokens out of logs and protecting secrets.\n\n## 4. Concrete example and explanation\nJWT has header, payload, and signature. The payload is readable, not a secret store. `exp` is expiry, `iss` the issuer, and `aud` the intended audience. Use a maintained library and a local test key.\n\n## 5. What to submit\nYour own GitHub repository, a redacted token example, a JWT validation checklist, and test results. Never submit real session tokens or secrets.\n\n## 6. How to check your work\nValidate signature, expiry, issuer, and audience. Reject changed and expired tokens; share no real tokens or keys in the report."},{"slug":"cybersecurity","task_number":7,"title":"API Security Checklist","old_description":"[[AZ]]\nKiçik REST API üçün endpoint, authz, data exposure və resource limit yoxlama checklist-i qur.\n\n[[EN]]\nCreate an endpoint, authorization, data-exposure, and resource-limit checklist for a small REST API.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nAPI üçün əsas təhlükəsizlik yoxlama siyahısı hazırlayıb onu öz test endpoint-lərində tətbiq edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz lab API-n, authentication, authorization, validation, rate limiting və təhlükəsiz error cavabları haqqında əsas bilik.\n\n## 3. Addım-addım icra\n1. Öz lab layihəni davam etdir.\n2. Endpoint-ləri və tələb olunan icazələri siyahıya al.\n3. Input validation, ownership, rate limit, error response, CORS və secret handling üçün yoxlama maddələri yaz.\n4. Hər maddəni pass/fail/not tested kimi işarələ və sübut əlavə et.\n5. Ən azı 3 boşluğu riskə görə sıralayıb düzəliş planı hazırla.\n6. Dəyişiklikdən sonra uyğun testləri təkrar işə sal.\n\n## 4. Konkret nümunə və izah\nHər sətirdə yoxlama, sınaq üsulu, nəticə və sübut olsun. Məsələn: “B istifadəçisi A-nın qeydinə baxa bilmir” → lokal sorğu → 403/404 → redaktə edilmiş cavab. Yoxlamadığın maddəyə “keçdi” yazma.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, API security checklist, pass/fail sübutları və prioritetli düzəliş planı. İcazəsiz real API-ləri skan etmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nEndpoint və icazə siyahısı checklist-lə uyğun gəlir. 3 boşluq təsirə görə sıralanıb; düzəliş sonrası yoxlanan və hələ açıq qalan maddələr ayrıdır.\n\n[[EN]]\n## 1. Goal\nCreate a practical security checklist for an API and apply it to your own test endpoints.\n\n## 2. Before you start\nYour lab API and basics of authentication, authorization, validation, rate limiting, and safe error responses.\n\n## 3. Step-by-step work\n1. Continue your own lab project.\n2. List endpoints and required permissions.\n3. Add checks for input validation, ownership, rate limits, error responses, CORS, and secret handling.\n4. Mark each item pass/fail/not tested and include evidence.\n5. Rank at least three gaps by risk and prepare a remediation plan.\n6. Rerun relevant tests after changes.\n\n## 4. Concrete example and explanation\nFor each row record check, method, result, and evidence. Example: “B cannot read A’s record” → local request → 403/404 → redacted response. Mark untested items as untested.\n\n## 5. What to submit\nYour own GitHub repository, API security checklist, pass/fail evidence, and prioritized remediation plan. Do not scan real APIs without authorization.\n\n## 6. How to check your work\nMatch the checklist to endpoint permissions. Prioritize three gaps by impact and distinguish retested fixes from open issues.","new_description":"[[AZ]]\nKiçik REST API üçün endpoint, authz, data exposure və resource limit yoxlama checklist-i qur.\n\nPulsuz alətlər: Google Docs (personal), Python (free). Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nCreate an endpoint, authorization, data-exposure, and resource-limit checklist for a small REST API.\n\nFree tools: Google Docs (personal), Python (free). Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** Lokal `GET /tasks/{id}` üçün authentication, owner authorization, input validation, rate limiting checklist-i yaz.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / cybersecurity / task-7` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. Öz demo API route-larını və mümkün riskləri siyahıya al. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. Auth, BOLA, məlumat sızması və rate limit üzrə pass/fail meyarı qur. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Hər risk üçün bir təhlükəsiz lokal test və düzəliş addımı yaz. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: Lokal `GET /tasks/{id}` üçün authentication, owner authorization, input validation, rate limiting checklist-i yaz. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\nLokal `GET /tasks/{id}` üçün authentication, owner authorization, input validation, rate limiting checklist-i yaz.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nAPI üçün əsas təhlükəsizlik yoxlama siyahısı hazırlayıb onu öz test endpoint-lərində tətbiq edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz lab API-n, authentication, authorization, validation, rate limiting və təhlükəsiz error cavabları haqqında əsas bilik.\n\n## 3. Addım-addım icra\n1. Öz lab layihəni davam etdir.\n2. Endpoint-ləri və tələb olunan icazələri siyahıya al.\n3. Input validation, ownership, rate limit, error response, CORS və secret handling üçün yoxlama maddələri yaz.\n4. Hər maddəni pass/fail/not tested kimi işarələ və sübut əlavə et.\n5. Ən azı 3 boşluğu riskə görə sıralayıb düzəliş planı hazırla.\n6. Dəyişiklikdən sonra uyğun testləri təkrar işə sal.\n\n## 4. Konkret nümunə və izah\nHər sətirdə yoxlama, sınaq üsulu, nəticə və sübut olsun. Məsələn: “B istifadəçisi A-nın qeydinə baxa bilmir” → lokal sorğu → 403/404 → redaktə edilmiş cavab. Yoxlamadığın maddəyə “keçdi” yazma.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, API security checklist, pass/fail sübutları və prioritetli düzəliş planı. İcazəsiz real API-ləri skan etmə.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nEndpoint və icazə siyahısı checklist-lə uyğun gəlir. 3 boşluq təsirə görə sıralanıb; düzəliş sonrası yoxlanan və hələ açıq qalan maddələr ayrıdır.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Build a safety checklist for a fictional local GET /tasks/{id} endpoint.\n\n## Free tools and platforms — getting started\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / cybersecurity / task-7` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. List routes and realistic threats in your own demo API. Demonstrate it with source code, a test, file or diagram.\n4. Define pass/fail tests for auth, BOLA, data exposure and rate limits. Demonstrate it with source code, a test, file or diagram.\n5. Specify one authorized local test and remediation for each risk. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Build a safety checklist for a fictional local GET /tasks/{id} endpoint. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nBuild a safety checklist for a fictional local GET /tasks/{id} endpoint.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nCreate a practical security checklist for an API and apply it to your own test endpoints.\n\n## 2. Before you start\nYour lab API and basics of authentication, authorization, validation, rate limiting, and safe error responses.\n\n## 3. Step-by-step work\n1. Continue your own lab project.\n2. List endpoints and required permissions.\n3. Add checks for input validation, ownership, rate limits, error responses, CORS, and secret handling.\n4. Mark each item pass/fail/not tested and include evidence.\n5. Rank at least three gaps by risk and prepare a remediation plan.\n6. Rerun relevant tests after changes.\n\n## 4. Concrete example and explanation\nFor each row record check, method, result, and evidence. Example: “B cannot read A’s record” → local request → 403/404 → redacted response. Mark untested items as untested.\n\n## 5. What to submit\nYour own GitHub repository, API security checklist, pass/fail evidence, and prioritized remediation plan. Do not scan real APIs without authorization.\n\n## 6. How to check your work\nMatch the checklist to endpoint permissions. Prioritize three gaps by impact and distinguish retested fixes from open issues."},{"slug":"cybersecurity","task_number":8,"title":"ZAP Passive Scan","old_description":"[[AZ]]\nOWASP ZAP-ın passive scan rejimi ilə yalnız lokal toy tətbiqin response-larını yoxla.\n\n[[EN]]\nUse OWASP ZAP passive scanning to review responses from a local toy application only.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nOWASP ZAP-ın passive scan nəticələrini təhlükəsiz lab-da oxuyub yanlış pozitivləri ayırd edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz lab tətbiqin və ya yazılı icazə verilmiş test target-i, HTTP/headers əsasları və ZAP hesabatı oxuma bacarığı. İcazəsiz sayt skan etmə.\n\n## 3. Addım-addım icra\n1. Öz lab repo-nu davam etdir.\n2. ZAP-ı yalnız localhost və ya yazılı icazə verilmiş target-ə yönəlt.\n3. Passive scan istifadə et; aktiv hücum/active scan başlatma.\n4. Tapıntıların adını, severity-ni, evidence-ni və təsirlənən URL-i qeyd et; həssas məlumatı redaktə et.\n5. Hər tapıntını əl ilə nəzərdən keçir və real problem, yanlış pozitiv, yoxlanmayıb kimi təsnif et.\n6. Ən vacib 2–3 tapıntı üçün düzəliş təklifi və retest planı yaz.\n\n## 4. Konkret nümunə və izah\nPassive scan brauzerin normal trafikini oxuyub təhlil edir. ZAP-ı işə sal, öz lokal səhifəni onun brauzerindən aç və passiv nəticələri oxu; Active Scan düyməsini başlatma. Şübhəli tapıntını avtomatik təsdiqlənmiş problem sayma.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, redaktə edilmiş ZAP passive report, finding triage cədvəli və düzəliş/retest planı. Target-in icazəli olduğunu sənədləşdir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHədəf ünvanı və passiv rejim qeyd olunub. Həqiqi problem, yanlış pozitiv və yoxlanmayan tapıntı ayrılıb; tapıntı yoxdursa bu da dürüst yazılıb.\n\n[[EN]]\n## 1. Goal\nReview OWASP ZAP passive-scan findings in a safe lab and distinguish likely issues from false positives.\n\n## 2. Before you start\nYour own lab app or a target with written authorization, HTTP/header basics, and the ability to read a ZAP report. Do not scan sites without permission.\n\n## 3. Step-by-step work\n1. Continue your own lab repository.\n2. Point ZAP only at localhost or an explicitly authorized target.\n3. Use passive scanning only; do not start active attacks/scans.\n4. Record finding name, severity, evidence, and affected URL; redact sensitive data.\n5. Review each finding manually and label it confirmed, false positive, or unverified.\n6. Suggest fixes and retest plans for the two or three highest-priority findings.\n\n## 4. Concrete example and explanation\nPassive scanning analyzes normal browser traffic. Start ZAP, browse your local page through its browser, and inspect passive results; do not start Active Scan. An alert is not automatically a confirmed vulnerability.\n\n## 5. What to submit\nYour own GitHub repository, a redacted ZAP passive report, a finding-triage table, and remediation/retest plan. Document authorization for the target.\n\n## 6. How to check your work\nRecord the target and passive mode. Distinguish confirmed issues, false positives, and unverified alerts; report honestly if there are no alerts.","new_description":"[[AZ]]\nOWASP ZAP-ın passive scan rejimi ilə yalnız lokal toy tətbiqin response-larını yoxla.\n\nPulsuz alətlər: OWASP ZAP (passive only), Visual Studio Code, Google Docs (personal). Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nUse OWASP ZAP passive scanning to review responses from a local toy application only.\n\nFree tools: OWASP ZAP (passive only), Visual Studio Code, Google Docs (personal). Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** OWASP ZAP ilə yalnız `localhost` test serverinin passiv header/response müşahidəsini apar.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **OWASP ZAP (passive only)** — https://www.zaproxy.org. Yalnız localhost və ya açıq icazəli laboratoriyada passiv analiz apar; üçüncü tərəfi skan etmə.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / cybersecurity / task-8` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. Öz lab ünvanını təsdiqlə və ZAP Browser / passive proxy-ni hazırla. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. Yalnız passiv scan aktiv et; active scan və internet hədəfini istifadə etmə. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Görünən riskləri false positive ilə fərqləndir, ekran görüntüsü və düzəliş əlavə et. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: OWASP ZAP ilə yalnız `localhost` test serverinin passiv header/response müşahidəsini apar. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\nOWASP ZAP ilə yalnız `localhost` test serverinin passiv header/response müşahidəsini apar.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nOWASP ZAP-ın passive scan nəticələrini təhlükəsiz lab-da oxuyub yanlış pozitivləri ayırd edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz lab tətbiqin və ya yazılı icazə verilmiş test target-i, HTTP/headers əsasları və ZAP hesabatı oxuma bacarığı. İcazəsiz sayt skan etmə.\n\n## 3. Addım-addım icra\n1. Öz lab repo-nu davam etdir.\n2. ZAP-ı yalnız localhost və ya yazılı icazə verilmiş target-ə yönəlt.\n3. Passive scan istifadə et; aktiv hücum/active scan başlatma.\n4. Tapıntıların adını, severity-ni, evidence-ni və təsirlənən URL-i qeyd et; həssas məlumatı redaktə et.\n5. Hər tapıntını əl ilə nəzərdən keçir və real problem, yanlış pozitiv, yoxlanmayıb kimi təsnif et.\n6. Ən vacib 2–3 tapıntı üçün düzəliş təklifi və retest planı yaz.\n\n## 4. Konkret nümunə və izah\nPassive scan brauzerin normal trafikini oxuyub təhlil edir. ZAP-ı işə sal, öz lokal səhifəni onun brauzerindən aç və passiv nəticələri oxu; Active Scan düyməsini başlatma. Şübhəli tapıntını avtomatik təsdiqlənmiş problem sayma.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, redaktə edilmiş ZAP passive report, finding triage cədvəli və düzəliş/retest planı. Target-in icazəli olduğunu sənədləşdir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHədəf ünvanı və passiv rejim qeyd olunub. Həqiqi problem, yanlış pozitiv və yoxlanmayan tapıntı ayrılıb; tapıntı yoxdursa bu da dürüst yazılıb.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Use OWASP ZAP passive inspection only against an authorized localhost server.\n\n## Free tools and platforms — getting started\n- **OWASP ZAP (passive only)** — https://www.zaproxy.org. Use passive inspection only on localhost or expressly authorized labs; do not scan third parties.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / cybersecurity / task-8` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Confirm the localhost scope and configure the ZAP passive proxy. Demonstrate it with source code, a test, file or diagram.\n4. Use passive analysis only; do not launch active scans against external sites. Demonstrate it with source code, a test, file or diagram.\n5. Document findings, possible false positives and safe fixes. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Use OWASP ZAP passive inspection only against an authorized localhost server. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nUse OWASP ZAP passive inspection only against an authorized localhost server.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nReview OWASP ZAP passive-scan findings in a safe lab and distinguish likely issues from false positives.\n\n## 2. Before you start\nYour own lab app or a target with written authorization, HTTP/header basics, and the ability to read a ZAP report. Do not scan sites without permission.\n\n## 3. Step-by-step work\n1. Continue your own lab repository.\n2. Point ZAP only at localhost or an explicitly authorized target.\n3. Use passive scanning only; do not start active attacks/scans.\n4. Record finding name, severity, evidence, and affected URL; redact sensitive data.\n5. Review each finding manually and label it confirmed, false positive, or unverified.\n6. Suggest fixes and retest plans for the two or three highest-priority findings.\n\n## 4. Concrete example and explanation\nPassive scanning analyzes normal browser traffic. Start ZAP, browse your local page through its browser, and inspect passive results; do not start Active Scan. An alert is not automatically a confirmed vulnerability.\n\n## 5. What to submit\nYour own GitHub repository, a redacted ZAP passive report, a finding-triage table, and remediation/retest plan. Document authorization for the target.\n\n## 6. How to check your work\nRecord the target and passive mode. Distinguish confirmed issues, false positives, and unverified alerts; report honestly if there are no alerts."},{"slug":"cybersecurity","task_number":9,"title":"Secure Coding Fixes","old_description":"[[AZ]]\nTapılmış təhlükəsizlik qüsurunu kök səbəbdən düzəlt və regression test ilə bağlandığını təsdiqlə.\n\n[[EN]]\nFix a discovered security defect at its root cause and prove closure with a regression test.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nÖz test tətbiqində tapılmış təhlükəsiz kod problemini düzəldəcək və testlə təkrar yaranmasının qarşısını alacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz lab layihən, code review, test yazmaq və input validation/authorization əsasları. Yalnız öz kodunda və sintetik məlumatla işlə.\n\n## 3. Addım-addım icra\n1. Öz lab repo-nu davam etdir.\n2. Əvvəlki auditdən bir təsdiqlənmiş problem seç; real sistemdən exploit götürmə.\n3. Problemin necə təkrarlanacağını və istifadəçiyə təsirini yaz.\n4. Minimal düzəliş et və problemi göstərən regression test əlavə et.\n5. Bütün testləri yenidən işə sal və yan təsirləri yoxla.\n6. Diff-də nə dəyişdiyini və qalan riskləri izah et.\n\n## 4. Konkret nümunə və izah\nMəsələn, əvvəlki lokal testdə başqa istifadəçinin qeydi açılırsa, serverdə sahiblik yoxlamasını düzəlt. Əlavə etdiyin test düzəlişdən əvvəl uğursuz, sonra uğurlu olmalıdır; bu, eyni səhvin qayıtmasını tutan regression testdir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, finding izahı, düzəliş diff-i, regression test və test nəticələri. Həssas kod və ya credential paylaşma.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nBir təsdiqlənmiş problem üçün təkrarlama addımı, minimal kod dəyişikliyi və əvvəl/sonra test nəticəsi var. Digər mövcud testlər də keçir.\n\n[[EN]]\n## 1. Goal\nFix a confirmed security issue in your own test app and prevent regression with a test.\n\n## 2. Before you start\nYour own lab project, code review, testing, and input-validation/authorization basics. Work only with your own code and synthetic data.\n\n## 3. Step-by-step work\n1. Continue your own lab repository.\n2. Choose one confirmed issue from your earlier audit; do not copy an exploit from a real system.\n3. Document reproduction steps and user impact.\n4. Make a minimal fix and add a regression test that demonstrates the issue.\n5. Rerun all tests and check for side effects.\n6. Explain the diff and any remaining risks.\n\n## 4. Concrete example and explanation\nFor example, fix a server ownership check that exposed another fictional user’s record. The added regression test must fail before the fix and pass after it.\n\n## 5. What to submit\nYour own GitHub repository, finding explanation, fix diff, regression test, and test results. Do not share sensitive code or credentials.\n\n## 6. How to check your work\nProvide reproduction steps, a minimal change, and before/after test results for one confirmed issue. Existing tests still pass.","new_description":"[[AZ]]\nTapılmış təhlükəsizlik qüsurunu kök səbəbdən düzəlt və regression test ilə bağlandığını təsdiqlə.\n\nPulsuz alətlər: Visual Studio Code, Python (free), GitHub Free. Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nFix a discovered security defect at its root cause and prove closure with a regression test.\n\nFree tools: Visual Studio Code, Python (free), GitHub Free. Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** Lokal XSS nümunəsinə textContent və SQL nümunəsinə parametrləşmə əlavə edib regression test yaz.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n- **Python (free)** — https://www.python.org. Lokal Python qur, `.py` skriptləri və sintetik testləri terminaldan işlət.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / cybersecurity / task-9` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. Əvvəlki lab-ın iki real problemi üzrə before/after qeydi saxla. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. Kodda output encoding və parametrləşmiş SQL istifadə et. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Ən azı 4 testlə düzəlişin işlədiyini göstər və yalan müsbətləri yaz. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: Lokal XSS nümunəsinə textContent və SQL nümunəsinə parametrləşmə əlavə edib regression test yaz. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\nLokal XSS nümunəsinə textContent və SQL nümunəsinə parametrləşmə əlavə edib regression test yaz.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nÖz test tətbiqində tapılmış təhlükəsiz kod problemini düzəldəcək və testlə təkrar yaranmasının qarşısını alacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz lab layihən, code review, test yazmaq və input validation/authorization əsasları. Yalnız öz kodunda və sintetik məlumatla işlə.\n\n## 3. Addım-addım icra\n1. Öz lab repo-nu davam etdir.\n2. Əvvəlki auditdən bir təsdiqlənmiş problem seç; real sistemdən exploit götürmə.\n3. Problemin necə təkrarlanacağını və istifadəçiyə təsirini yaz.\n4. Minimal düzəliş et və problemi göstərən regression test əlavə et.\n5. Bütün testləri yenidən işə sal və yan təsirləri yoxla.\n6. Diff-də nə dəyişdiyini və qalan riskləri izah et.\n\n## 4. Konkret nümunə və izah\nMəsələn, əvvəlki lokal testdə başqa istifadəçinin qeydi açılırsa, serverdə sahiblik yoxlamasını düzəlt. Əlavə etdiyin test düzəlişdən əvvəl uğursuz, sonra uğurlu olmalıdır; bu, eyni səhvin qayıtmasını tutan regression testdir.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, finding izahı, düzəliş diff-i, regression test və test nəticələri. Həssas kod və ya credential paylaşma.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nBir təsdiqlənmiş problem üçün təkrarlama addımı, minimal kod dəyişikliyi və əvvəl/sonra test nəticəsi var. Digər mövcud testlər də keçir.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Fix local text rendering and parameterized-query examples and add regressions.\n\n## Free tools and platforms — getting started\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n- **Python (free)** — https://www.python.org. Install Python locally and run scripts with fictional test fixtures.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / cybersecurity / task-9` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Record before/after observations for two vulnerabilities in your local lab. Demonstrate it with source code, a test, file or diagram.\n4. Apply output encoding and parameterized SQL where relevant. Demonstrate it with source code, a test, file or diagram.\n5. Verify four tests and note any false positives. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Fix local text rendering and parameterized-query examples and add regressions. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nFix local text rendering and parameterized-query examples and add regressions.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nFix a confirmed security issue in your own test app and prevent regression with a test.\n\n## 2. Before you start\nYour own lab project, code review, testing, and input-validation/authorization basics. Work only with your own code and synthetic data.\n\n## 3. Step-by-step work\n1. Continue your own lab repository.\n2. Choose one confirmed issue from your earlier audit; do not copy an exploit from a real system.\n3. Document reproduction steps and user impact.\n4. Make a minimal fix and add a regression test that demonstrates the issue.\n5. Rerun all tests and check for side effects.\n6. Explain the diff and any remaining risks.\n\n## 4. Concrete example and explanation\nFor example, fix a server ownership check that exposed another fictional user’s record. The added regression test must fail before the fix and pass after it.\n\n## 5. What to submit\nYour own GitHub repository, finding explanation, fix diff, regression test, and test results. Do not share sensitive code or credentials.\n\n## 6. How to check your work\nProvide reproduction steps, a minimal change, and before/after test results for one confirmed issue. Existing tests still pass."},{"slug":"cybersecurity","task_number":10,"title":"Final Security Report","old_description":"[[AZ]]\nTəhlükəsizlik laboratoriyasının nəticələrini sübutlu, risk üzrə sıralanmış yekun hesabatda birləşdir.\n\n[[EN]]\nCombine security-lab results into an evidence-backed, risk-ranked final report.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nTəhlükəsizlik yoxlamasının nəticələrini rəhbər və developer üçün aydın, sübutlu hesabat şəklində təqdim edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–9 materialların, risk/severity anlayışı və remediation planı. Həqiqi test aparılmayıbsa, nəticəni uydurma.\n\n## 3. Addım-addım icra\n1. Öz lab repo-nun əvvəlki nəticələrini davam etdir.\n2. Əhatə dairəsini, icazəni, istifadə olunan alətləri və məhdudiyyətləri yaz.\n3. Finding-ləri təsir və ehtimala görə sıralayıb sübut əlavə et.\n4. Hər finding üçün risk, düzəliş, prioritet və retest addımı yaz.\n5. Şəxsi məlumat, token, cookie və həssas URL-ləri redaktə et.\n6. Qısa rəhbər xülasəsi və developer üçün texniki bölmə hazırla.\n\n## 4. Konkret nümunə və izah\nTapıntı kartı: ad → təsirlənən lokal funksiya → təkrarlama → sübut → təsir → düzəliş → təkrar yoxlamanın nəticəsi. Rəhbər üçün xülasə texniki detallardan əvvəl əsas risk və prioriteti izah etsin.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, təhlükəsizlik hesabatı, prioritetli remediation planı və retest statusu. Scope və məhdudiyyətlər açıq yazılmalı, yoxlanmayan iddialar fakt kimi göstərilməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHər tapıntı sübutla əlaqəlidir. Təsdiqlənməyən şübhələr ayrıca işarələnib; hesabatda icazə/sərhədlər, məhdudiyyətlər və düzəliş statusu var.\n\n[[EN]]\n## 1. Goal\nPresent security-review results in a clear, evidence-based report for both leadership and developers.\n\n## 2. Before you start\nYour artifacts from Tasks 1–9, risk/severity concepts, and remediation planning. Never invent results for tests you did not perform.\n\n## 3. Step-by-step work\n1. Continue the findings from your own lab.\n2. Document scope, authorization, tools, and limitations.\n3. Rank findings by impact and likelihood and include evidence.\n4. For each finding, state risk, fix, priority, and retest steps.\n5. Redact personal data, tokens, cookies, and sensitive URLs.\n6. Prepare an executive summary and a technical section for developers.\n\n## 4. Concrete example and explanation\nUse a finding card: title → affected local feature → reproduction → evidence → impact → fix → retest result. The executive summary states risks and priorities before technical detail.\n\n## 5. What to submit\nYour own GitHub repository, security report, prioritized remediation plan, and retest status. State scope and limitations clearly, and never present unverified claims as facts.\n\n## 6. How to check your work\nLink every finding to evidence. Label unconfirmed suspicions; document scope, permission, limitations, and remediation status.","new_description":"[[AZ]]\nTəhlükəsizlik laboratoriyasının nəticələrini sübutlu, risk üzrə sıralanmış yekun hesabatda birləşdir.\n\nPulsuz alətlər: Google Docs (personal), GitHub Free, Google Sheets (personal). Addım-addım bələdçini tapşırıqda oxu.\n\n[[EN]]\nCombine security-lab results into an evidence-backed, risk-ranked final report.\n\nFree tools: Google Docs (personal), GitHub Free, Google Sheets (personal). Read the detailed guide inside the assignment.","new_instructions":"[[AZ]]\n## Yeni başlayanlar üçün aydın izah\nBu məşqin nəticəsi praktiki və yoxlana bilən olmalıdır. **Tapşırığın sadə nümunəsi:** Risk cədvəlində 5 tapıntı üçün severity, təsir, sübut, fix və retest qeyd et.\n\n## Pulsuz proqram və platformalar — haradan başlamaq olar?\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n- **Google Sheets (personal)** — https://sheets.google.com. Sütun başlıqları, sintetik sətirlər və yoxlanıla bilən hesablamalar yarat.\n> Heç bir ödənişli abunə, kredit kartı və ya pullu API tələb olunmur; pulsuz limit çatmasa lokal/maket variantdan istifadə et. Başqalarının hesabını və ya sistemini icazəsiz sına.\n\n## Addım-addım necə etməli? — 8 mərhələ\n1. Lokal `Talora / cybersecurity / task-10` qovluğu yarat; əvvəlki layihənin nüsxəsini və yalnız sintetik/icazəli məlumatı hazırla.\n2. Bu tapşırığın məqsədini öz sözlərinlə bir cümlədə yaz, hansı nəticənin uğur sayıldığını müəyyən et.\n3. Yalnız öz lab testlərindən nəticələri topla, real sayta aid iddia yazma. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n4. Tapıntıları ehtimal/təsir əsasında prioritetləşdir və konkret düzəliş addımı ver. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n5. Sonda 3 əsas təhlükəsizlik dərsi və yoxlanmamış sahələri izah et. Təkcə şərh etmə: kod, sınaq, fayl və ya diaqramla nəticəni göstər.\n6. Praktik ssenarini sına: Risk cədvəlində 5 tapıntı üçün severity, təsir, sübut, fix və retest qeyd et. Uğurlu və mənfi halı müqayisə edib müşahidəni yaz.\n7. Aşağıdakı orijinal tələblərdə istənən GitHub repo/fayl/linki, README və test sübutunu hazırla; şəxsi məlumatları çıxart.\n8. 8 addımı yoxla, 3–5 cümləlik yekun yaz və orijinal rəsmi təhvil meyarlarını ayrıca təsdiqlə.\n\n## Konkret nümunə və gözlənilən nəticə\nRisk cədvəlində 5 tapıntı üçün severity, təsir, sübut, fix və retest qeyd et.\nBu, başlanğıc nümunəsidir: öz versiyanı hazırla, uğurlu və uğursuz davranışı yoxla, səbəbini izah et.\n\n## Nəyi göndərməlisən?\n- Aşağıdakı **əvvəlki rəsmi tapşırığın tələb etdiyi** fayl/GitHub/link. Təqdimat növü dəyişmir.\n- Mənbə faylı və qısa README; necə işə salındığı və hansı pulsuz alətlərin istifadə edildiyi.\n- Lokal testin nəticəsi, screenshot və ya sintetik test dataseti; 3–5 cümləlik nəticə, mənbə istinadları.\n- Şəxsi məlumat, şifrə, token, başqasının gizli sənədi və icazəsiz sınaq olmamalıdır.\n\n## Özünü yoxlama üçün 100 ballıq nümunə meyar\n- **40:** əsas texniki addımlar tamamlanıb və orijinal tələb olunan material var.\n- **25:** düzgün nümunə, xəta halı və sübutla yoxlama var.\n- **15:** fayl quruluşu, aydın README, oxunaqlı təqdimat var.\n- **10:** təhlükəsizlik, müəllif hüquqları və pulsuz istifadə qaydalarına əməl edilib.\n- **10:** öz izahın və görülə biləcək təkmilləşdirmələr var.\n**Bu sadəcə öyrənmə rubrikidir, əvvəlki qiymətləndirmə və təqdimat şərtlərini dəyişmir.**\n\n## Göndərməzdən əvvəl\n- Kod və fayl açılır, linkə baxmaq olur, məxfi məlumat yoxdur.\n- Praktik ssenari işlədilib, sadəcə nəzəri cavab göndərilməyib.\n- Əvvəlki rəsmi tapşırıq şərtlərinin hər biri saxlanılıb.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunub)\n## 1. Bu tapşırıq nə üçündür?\nTəhlükəsizlik yoxlamasının nəticələrini rəhbər və developer üçün aydın, sübutlu hesabat şəklində təqdim edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–9 materialların, risk/severity anlayışı və remediation planı. Həqiqi test aparılmayıbsa, nəticəni uydurma.\n\n## 3. Addım-addım icra\n1. Öz lab repo-nun əvvəlki nəticələrini davam etdir.\n2. Əhatə dairəsini, icazəni, istifadə olunan alətləri və məhdudiyyətləri yaz.\n3. Finding-ləri təsir və ehtimala görə sıralayıb sübut əlavə et.\n4. Hər finding üçün risk, düzəliş, prioritet və retest addımı yaz.\n5. Şəxsi məlumat, token, cookie və həssas URL-ləri redaktə et.\n6. Qısa rəhbər xülasəsi və developer üçün texniki bölmə hazırla.\n\n## 4. Konkret nümunə və izah\nTapıntı kartı: ad → təsirlənən lokal funksiya → təkrarlama → sübut → təsir → düzəliş → təkrar yoxlamanın nəticəsi. Rəhbər üçün xülasə texniki detallardan əvvəl əsas risk və prioriteti izah etsin.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, təhlükəsizlik hesabatı, prioritetli remediation planı və retest statusu. Scope və məhdudiyyətlər açıq yazılmalı, yoxlanmayan iddialar fakt kimi göstərilməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nHər tapıntı sübutla əlaqəlidir. Təsdiqlənməyən şübhələr ayrıca işarələnib; hesabatda icazə/sərhədlər, məhdudiyyətlər və düzəliş statusu var.\n\n[[EN]]\n## Clear beginner explanation\nThis is a practical assignment with a verifiable outcome. **Beginner example:** Create a five-finding report with severity, impact, evidence, fix and retest.\n\n## Free tools and platforms — getting started\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n- **Google Sheets (personal)** — https://sheets.google.com. Create labeled columns, fictional sample records and verifiable calculations.\n> No paid plan, credit card or paid API is required. Use a local mock if a free quota is exhausted. Never probe systems or accounts without permission.\n\n## Step-by-step — 8 stages\n1. Create a local `Talora / cybersecurity / task-10` folder with earlier source files and fictional/authorized data.\n2. State the purpose in your own words and define an observable success criterion.\n3. Use findings from your own lab only, without claims about external services. Demonstrate it with source code, a test, file or diagram.\n4. Prioritize findings by probability/impact and document actionable fixes. Demonstrate it with source code, a test, file or diagram.\n5. Summarize three lessons and any untested areas. Demonstrate it with source code, a test, file or diagram.\n6. Test this scenario: Create a five-finding report with severity, impact, evidence, fix and retest. Compare a successful and negative case and record observations.\n7. Prepare the exact original file/repository/link plus README and test evidence without personal data.\n8. Review all eight steps, write a short conclusion and verify all official original requirements.\n\n## Practical example and expected behavior\nCreate a five-finding report with severity, impact, evidence, fix and retest.\nUse it as a starting point, create your own version and check both valid and invalid cases.\n\n## Required deliverables\n- The **original required file/GitHub repository/link** below; submission type is unchanged.\n- Source files and a short README explaining setup and free tools.\n- Local test logs, screenshots or fictional fixtures plus a short conclusion and citations.\n- No passwords, tokens, private data, unauthorized scanning or unlicensed assets.\n\n## Learning self-check rubric (100 points)\n- **40:** completed technical steps and original required deliverables.\n- **25:** demonstrated correct result, negative test and reproducible evidence.\n- **15:** clear project structure and README.\n- **10:** safety, attribution and free-tool constraints.\n- **10:** explanation, limits and next improvements.\n**This rubric is illustrative; it does not alter original grading or previously submitted work.**\n\n## Before submission\n- Files and links work and contain no confidential information.\n- Demonstrated practical results instead of theory alone.\n- Original requirements and submission type remain authoritative.\n\n## Original official requirements (preserved)\n## 1. Goal\nPresent security-review results in a clear, evidence-based report for both leadership and developers.\n\n## 2. Before you start\nYour artifacts from Tasks 1–9, risk/severity concepts, and remediation planning. Never invent results for tests you did not perform.\n\n## 3. Step-by-step work\n1. Continue the findings from your own lab.\n2. Document scope, authorization, tools, and limitations.\n3. Rank findings by impact and likelihood and include evidence.\n4. For each finding, state risk, fix, priority, and retest steps.\n5. Redact personal data, tokens, cookies, and sensitive URLs.\n6. Prepare an executive summary and a technical section for developers.\n\n## 4. Concrete example and explanation\nUse a finding card: title → affected local feature → reproduction → evidence → impact → fix → retest result. The executive summary states risks and priorities before technical detail.\n\n## 5. What to submit\nYour own GitHub repository, security report, prioritized remediation plan, and retest status. State scope and limitations clearly, and never present unverified claims as facts.\n\n## 6. How to check your work\nLink every finding to evidence. Label unconfirmed suspicions; document scope, permission, limitations, and remediation status."}]$legacy_payload$::jsonb);
DO $preflight$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='cybersecurity' AND t.title=e.item->>'title' AND t.instructions=e.item->>'old_instructions'
 AND t.description=e.item->>'old_description' AND t.status='published' AND t.is_required;
 IF (SELECT jsonb_array_length(payload) FROM legacy_guides)<>10 OR n<>10 THEN RAISE EXCEPTION 'Version mismatch for cybersecurity: %',n; END IF;
END; $preflight$;
DO $apply$
DECLARE n integer;
BEGIN
 UPDATE public.internship_tasks t SET instructions=e.item->>'new_instructions',description=e.item->>'new_description'
 FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 WHERE i.slug='cybersecurity' AND t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 AND t.title=e.item->>'title' AND t.instructions=e.item->>'old_instructions' AND t.description=e.item->>'old_description';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>10 THEN RAISE EXCEPTION 'Only % tasks changed for cybersecurity',n; END IF;
END; $apply$;
DO $verify$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='cybersecurity' AND t.instructions=e.item->>'new_instructions' AND t.description=e.item->>'new_description'
 AND t.status='published' AND t.is_required;
 IF n<>10 THEN RAISE EXCEPTION 'Post-update verification failed cybersecurity: %',n; END IF;
END; $verify$;
COMMIT;
